function loadRecords(dir) {
  const raw = path.join(dir, 'records.jsonl');
  if (fs.existsSync(raw)) return verifyAndRead(raw);
  const gz = path.join(dir, 'records.jsonl.gz');
  const bytes = gunzipSync(fs.readFileSync(gz));
  if (sha256(bytes) !== manifest.records_sha256) throw new ReleaseUnavailable('sha mismatch');
  return bytes;
}
